// Fetch every registered ClickUp list and build the raw rows in one pass.
//
// Snapshot policy (version history without unbounded growth):
//   - plan lists (list_kind 'promo') are written in full on EVERY run, so the newest
//     ingested_at of a list is a complete picture: a task deleted in ClickUp drops out
//     of stg.stg_clickup_plan on the next hourly run (about 40 tasks, ~8 MB a day);
//   - creative lists (ad_pipeline, concepts, personas): the first run of each UTC day
//     writes every task and field definition (full daily snapshot), later runs that day
//     write a task only when its date_updated or list changed, and a field definition
//     only when its name, type, target list or options changed.
// So raw holds at most one row per task per hour.
//
// Header is `Authorization: pk_...` with NO Bearer prefix (Bearer gives OAUTH_019).
const helpers = this.helpers;
const sleep = ms => new Promise(r => setTimeout(r, ms));

const RUN_STARTED_AT = new Date().toISOString();
const INGESTED_AT = RUN_STARTED_AT;
const today = INGESTED_AT.slice(0, 10);

const token = Buffer.from($('Get ClickUp token').first().json.payload.data, 'base64').toString('utf8').trim();
if (!token) throw new Error('Secret clickup-api-token decoded to an empty string.');

const lists = $('Read list registry').all().map(i => i.json).filter(l => l && l.list_id);
if (!lists.length) throw new Error('ref.clickup_lists returned no active list for an active client.');

const stateRaw = $('Read snapshot state').first().json.state;
const state = stateRaw ? JSON.parse(stateRaw) : {};
const taskSig = new Map((state.tasks || []).map(x => [x.k, x.s]));
const fieldSig = new Map((state.fields || []).map(x => [x.k, x.s]));
const ALWAYS_FULL = new Set(['promo']);

const get = async (url, qs) => {
  for (let attempt = 0; attempt < 5; attempt++) {
    const r = await helpers.httpRequest({
      method: 'GET', url, qs,
      headers: { Authorization: token, Accept: 'application/json' },
      returnFullResponse: true, json: true, ignoreHttpStatusErrors: true, timeout: 60000
    });
    if (r.statusCode === 429 || r.statusCode >= 500) {
      await sleep(2000 * Math.pow(2, attempt));
      continue;
    }
    if (r.statusCode !== 200) {
      const body = typeof r.body === 'string' ? r.body : JSON.stringify(r.body || {});
      throw new Error('ClickUp HTTP ' + r.statusCode + ' on ' + url + ': ' + body.slice(0, 300));
    }
    return r.body;
  }
  throw new Error('ClickUp kept returning 429/5xx on ' + url);
};

const ts = v => (v ? new Date(Number(v)).toISOString() : null);
const label = (def, value) => {
  if (value === null || value === undefined || value === '') return null;
  const opts = (def && def.options) || [];
  const byIndex = opts.find(o => String(o.orderindex) === String(value));
  const byId = opts.find(o => String(o.id) === String(value));
  const hit = byIndex || byId;
  return hit ? (hit.name ?? null) : null;
};

const fieldRows = [];
const taskRows = [];
const listErrors = [];
const stats = [];

for (const ctx of lists) {
  const listId = String(ctx.list_id);
  try {
    // Field definitions
    const fbody = await get('https://api.clickup.com/api/v2/list/' + listId + '/field');
    const fields = (fbody && fbody.fields) || [];
    const defs = new Map();
    let fieldsWritten = 0;
    for (const f of fields) {
      const cfg = f.type_config || {};
      const target = cfg.subcategory_id ? String(cfg.subcategory_id) : null;
      const optionsJson = JSON.stringify(cfg.options || []);
      defs.set(f.id, { name: f.name, type: f.type, options: cfg.options || [] });
      const k = ctx.client_id + '|' + listId + '|' + f.id;
      const s = (f.name || '') + '|' + (f.type || '') + '|' + (target || '') + '|' + optionsJson;
      if (!ALWAYS_FULL.has(ctx.list_kind) && fieldSig.get(k) === s) continue;
      fieldsWritten++;
      fieldRows.push({
        client_id: ctx.client_id, ingested_at: INGESTED_AT, snapshot_date: today,
        list_kind: ctx.list_kind, list_id: listId, field_id: f.id,
        name: f.name ?? null, type: f.type ?? null, target_list_id: target,
        options_json: optionsJson, payload_json: JSON.stringify(f)
      });
    }
    await sleep(250);

    // Tasks, paginated (100 per page)
    const tasks = [];
    for (let page = 0; page < 40; page++) {
      const body = await get('https://api.clickup.com/api/v2/list/' + listId + '/task',
        { include_closed: 'true', subtasks: 'false', page: String(page) });
      const batch = (body && body.tasks) || [];
      tasks.push(...batch);
      await sleep(250);
      if (body.last_page === true || batch.length < 100) break;
      if (page === 39) throw new Error('List ' + listId + ' has more than 40 pages of tasks; raise the page cap.');
    }

    let tasksWritten = 0;
    for (const t of tasks) {
      const k = ctx.client_id + '|' + String(t.id);
      const s = String(t.date_updated ?? '') + '|' + listId;
      if (!ALWAYS_FULL.has(ctx.list_kind) && taskSig.get(k) === s) continue;
      tasksWritten++;
      const custom = (t.custom_fields || []).map(f => {
        const def = defs.get(f.id) || { name: f.name, type: f.type, options: (f.type_config || {}).options || [] };
        const v = f.value;
        let value_text = null, value_num = null, value_ids = [];
        if (f.type === 'drop_down') {
          value_text = label(def, v);
        } else if (f.type === 'list_relationship' || f.type === 'tasks') {
          value_ids = Array.isArray(v) ? v.map(x => String(x.id ?? x)) : [];
          value_text = Array.isArray(v) ? (v.map(x => x.name).filter(Boolean).join(', ') || null) : null;
        } else if (f.type === 'number' || f.type === 'currency') {
          const n = (v === null || v === undefined || v === '') ? null : Number(v);
          value_num = (n === null || !Number.isFinite(n)) ? null : n;
        } else if (f.type === 'date') {
          value_text = v ? new Date(Number(v)).toISOString().slice(0, 10) : null;
        } else if (f.type === 'labels') {
          const opts = def.options || [];
          value_text = Array.isArray(v)
            ? (v.map(id => { const o = opts.find(x => x.id === id); return o ? (o.label ?? null) : null; }).filter(Boolean).join(', ') || null)
            : null;
        } else {
          value_text = (v === null || v === undefined || v === '') ? null
            : (typeof v === 'object' ? JSON.stringify(v) : String(v));
        }
        // A value identical to its own field's name is a placeholder, not data.
        if (value_text !== null && value_text.trim() === (f.name || '').trim()) value_text = null;
        return { field_id: f.id, name: f.name, type: f.type, value_text, value_num, value_ids };
      });
      taskRows.push({
        client_id: ctx.client_id, ingested_at: INGESTED_AT, snapshot_date: today,
        list_kind: ctx.list_kind, list_id: listId, task_id: String(t.id),
        task_name: t.name ?? '', task_url: t.url ?? null,
        status: (t.status && t.status.status) ?? null, status_type: (t.status && t.status.type) ?? null,
        date_created: ts(t.date_created), date_updated: ts(t.date_updated), date_closed: ts(t.date_closed),
        assignees: (t.assignees || []).map(a => a.username || a.email).filter(Boolean),
        custom_fields: custom,
        payload_json: JSON.stringify(t)
      });
    }
    stats.push({ client_id: ctx.client_id, list_kind: ctx.list_kind, list_id: listId,
      fields: fields.length, fields_written: fieldsWritten, tasks: tasks.length, tasks_written: tasksWritten });
  } catch (e) {
    listErrors.push(ctx.client_id + '/' + ctx.list_kind + ' (' + listId + '): ' + String(e.message || e).slice(0, 300));
  }
}

return [{ json: {
  run_started_at: RUN_STARTED_AT,
  ingested_at: INGESTED_AT,
  snapshot_date: today,
  lists: lists.length,
  tasks_seen: stats.reduce((a, s) => a + s.tasks, 0),
  expected_task_rows: taskRows.length,
  expected_field_rows: fieldRows.length,
  list_errors: listErrors.join(' | '),
  stats,
  field_rows: fieldRows,
  task_rows: taskRows
} }];

const s = $('Fetch ClickUp lists').first().json;
if (!s.field_rows || !s.field_rows.length) return [{ json: { __skip: true } }];
return s.field_rows.map(r => ({ json: r }));

const s = $('Fetch ClickUp lists').first().json;
if (!s.task_rows || !s.task_rows.length) return [{ json: { __skip: true } }];
return s.task_rows.map(r => ({ json: r }));

