INSERT INTO `oneeighty-warehouse.ops.pipeline_log`
  (run_id, workflow, client_id, source, started_at, finished_at, duration_seconds, status, rows_loaded, error_msg, trigger)
VALUES (
  @run_id, 'wf_clickup_to_bigquery', NULL, 'plan_pacing',
  CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP(), NULL,
  @status, NULL, IF(@msg = 'none', 'CALL mart.sp_refresh_plan_pacing()', CONCAT('CALL mart.sp_refresh_plan_pacing() failed: ', @msg)), @trigger)
